// One row per Aimfox account per day, from the account's own numbers.
// Fixes, rather than ports, four defects of branch L (see the workflow README).
const client = $('[S] Loop clients').first().json;
const accJson = $('[S] Accounts').first().json || {};
const accounts = Array.isArray(accJson.accounts) ? accJson.accounts : [];

const out = { client_id: client.client_id, client: client.name, accounts: accounts.length,
              skipped: null, payload: '[]' };

// Interactions are a WORKSPACE-level series; the API's per-account filter could not be verified
// (account_ids 500s, and no client has more than one account to tell a working filter from an
// ignored one). Attributing a workspace total to one of several accounts would be a guess.
if (accounts.length !== 1) {
  out.skipped = accounts.length === 0 ? 'no LinkedIn account connected'
                                      : `${accounts.length} accounts — cannot attribute workspace interactions`;
  return [{ json: out }];
}
const account = accounts[0];

const num = v => { const n = Number(v); return Number.isFinite(n) ? n : 0; };

// The FIRST bucket of a single-day query is a boundary artefact and lies: asked for 2026-07-20 it
// returned sent=0 where the true value was 33. Only the last bucket describes the requested day.
const buckets = $('[S] Interactions').first().json?.buckets || [];
const last = buckets.length ? buckets[buckets.length - 1] : null;
const invitesSent = last ? num(last.sent_connections) : null;
const invitesAccepted = last ? num(last.accepted_connections) : null;

// limit.connect is the WEEKLY cap; the daily allowance is a fifth of it (process invariant).
const weeklyCap = num($('[S] Account limits').first().json?.limit?.connect);
const dailyLimit = weeklyCap ? Math.floor(weeklyCap / 5) : null;

// Single subtraction. Branch L computes daily - buckets[1] - buckets[0] and double-counts.
const remaining = (dailyLimit === null || invitesSent === null)
  ? null : Math.max(dailyLimit - invitesSent, 0);

// Remaining database = this client's ACTIVE campaigns, LOADED AUDIENCE minus already-sent.
// `target_count` is that audience; `audience_size` is a fixed vendor ceiling and was the bug.
// The ACTIVE filter moved here from `[S] Campaign totals`, which now emits every campaign so the
// per-campaign metrics can be stored regardless of state.
//
// NOTE: `remaining_database_size` is deprecated as of 2026-08-19 and nothing reads it — the clients
// grid derives the same number from campaigns.database_size - campaigns.invites_sent. It is still
// written, and written correctly, by explicit decision: a retired column holding a right number
// beats one holding a wrong one.
let remainingDb = null;
const details = [];
try {
  for (const it of $input.all()) {
    const j = it.json || {};
    if (!j || j.error || !j.metrics || j.state !== 'ACTIVE') continue;
    details.push(j);
  }
} catch (e) { /* no campaign items */ }
if (details.length) {
  remainingDb = details.reduce((s, d) => s + Math.max(num(d.target_count) - num(d.sent_connections), 0), 0);
}

const reportDate = $now.toFormat('yyyy-MM-dd');
out.payload = JSON.stringify([{
  client_id: client.client_id,
  profile_id: String(account.id),
  report_date: reportDate,
  invites_sent: invitesSent,
  invites_accepted: invitesAccepted,
  invite_limit: weeklyCap || null,
  invite_limit_remaining: remaining,
  remaining_database_size: remainingDb,
  schedule_today: remaining,
  schedule_tomorrow: dailyLimit,
  schedule_day_after: dailyLimit,
}]);
return [{ json: out }];

// One multi-row UPDATE for this client's campaigns.
//
// UPDATE only, never INSERT. The campaign catalog is owned by `aimfox-campaign-sync`; a campaign it
// has not synced yet waits for the next hour rather than being half-created here with no name, no
// client and no type. Two workflows write one row, on DISJOINT column sets — the same discipline
// campaign-sync already applies to `type` / `sequencer_id`.
const rows = $input.all().map((i) => i.json).filter((j) => j && j.metrics && j.external_id);
if (!rows.length) return [{ json: { sql: 'SELECT 1', count: 0 } }];

const safe = (s) => String(s ?? '').replace(/'/g, "''");
const n = (v) => { const x = Number(v); return Number.isFinite(x) ? Math.trunc(x) : 0; };

// Every value is cast: a single-row VALUES list otherwise leaves Postgres to infer, and `unknown`
// against a text column is a runtime error rather than a wrong answer, but still an outage.
const values = rows.map((r) =>
  `('${safe(r.external_id)}'::text, ${n(r.sent_connections)}::int, ${n(r.accepted_connections)}::int, ${n(r.message_steps)}::int)`
).join(',\n');

const sql = `
UPDATE public.campaigns c SET
  invites_sent      = v.sent,
  invites_accepted  = v.accepted,
  message_steps     = v.steps,
  metrics_synced_at = NOW()
FROM (VALUES
${values}
) AS v(external_id, sent, accepted, steps)
WHERE c.external_id = v.external_id
  AND c.sequencer_id = '00000000-0000-4000-a000-000000000003'::uuid
RETURNING c.external_id, c.invites_sent, c.invites_accepted, c.message_steps
`;
return [{ json: { sql, count: rows.length } }];

// Pairs each campaign's detail with its own metrics, and emits ONE ITEM PER CAMPAIGN.
//
// Two deliberate changes from the version that only fed remaining-database:
//  1. no ACTIVE filter here. `[S] Campaign metrics SQL` stores the numbers for every campaign, so a
//     campaign changing state later does not erase what it did; `[S] Build row` applies the ACTIVE
//     filter itself, where it actually means something.
//  2. `target_count`, not `audience_size`. audience_size is a fixed vendor ceiling — 10000 for every
//     `list` campaign and 2500 for a `navigator` one, probed across all nine keyed workspaces on
//     2026-08-19 — and using it made remaining-database ~20x too large (Bent Iron PL: 19968 stored
//     against a real 918). target_count is the loaded audience, and it is what campaigns.database_size
//     already carries.
const det = $('[S] Campaign detail').all();
const items = $input.all();

// Detail and metrics are paired BY INDEX: the metrics call is made per detail item and its response
// carries no campaign id, so there is nothing else to pair on. Both HTTP nodes continue on error, so
// the lengths should always match — if they ever do not, emit nothing rather than attribute one
// campaign's sent count to another campaign's audience.
if (det.length !== items.length) {
  return [{ json: { metrics: false, skipped: `detail/metrics length mismatch (${det.length} vs ${items.length})` } }];
}

const num = (v) => { const n = Number(v); return Number.isFinite(n) ? n : 0; };
const out = [];
items.forEach((it, i) => {
  const m = it.json?.metrics;
  const c = det[i]?.json?.campaign;
  if (!m || !c) return;

  // The LinkedIn service level, straight from the vendor. `outreach_type` is 'connect' on every
  // campaign in every workspace and distinguishes nothing; the message sequence lives in the
  // PRIMARY_CONNECT flow's `flow_message_templates`. 0 of them = invitations only, >0 = full campaign.
  const steps = (Array.isArray(c.flows) ? c.flows : []).reduce(
    (s, f) => s + (Array.isArray(f?.flow_message_templates) ? f.flow_message_templates.length : 0),
    0,
  );

  out.push({ json: {
    metrics: true,
    external_id: String(c.id ?? ''),
    state: String(c.state ?? '').toUpperCase(),
    target_count: num(c.target_count),
    sent_connections: num(m.sent_connections),
    accepted_connections: num(m.accepted_connections),
    message_steps: steps,
  } });
});
return out.length ? out : [{ json: {} }];

const toNumber = (value) => {
  const number = Number(value);
  return Number.isFinite(number) ? number : 0;
};

return {
  json: {
    account_id: $('Filter1').item.json.row_number,
    workspace_id: $('Filter1').item.json.col_5, 
    campaign_id: $('Filter').item.json.campaigns.id,

    sent: toNumber($json.metrics.sent_connections),
    accepted: toNumber($json.metrics.accepted_connections),
    audience: toNumber($('Get Campaign').item.json.campaign.audience_size),

    // приклад показника, який треба віднімати
    remaining_audience:
      toNumber($('Get Campaign').item.json.campaign.audience_size) -
      toNumber($json.metrics.sent_connections)
  }
};

const toNumber = (value) => {
  const number = Number(value);
  return Number.isFinite(number) ? number : 0;
};

return {
  json: {
    account_id: $('Filter1').item.json.row_number,
    daily_limit: toNumber($('Summarize1').item.json.sum_limit_connect)/5,
    sent_today: toNumber($json.buckets[1].sent_connections-$json.buckets[0].sent_connections),
    sent_connections: toNumber($json.buckets[1].sent_connections) - $json.buckets[0].sent_connections,
    workspace_id: $('Filter1').item.json.col_5,

    remaining_limit:
      toNumber($('Summarize1').item.json.sum_limit_connect)/5 -
      toNumber($json.buckets[1].sent_connections) -
      toNumber($json.buckets[0].sent_connections)
  }
};

const toNumber = (value) => {
  const number = Number(value);
  return Number.isFinite(number) ? number : 0;
};

const aggregateData = $('Aggregate1').item.json.data || [];

const accountId =
  aggregateData[1]?.account_id ??
  aggregateData[0]?.account_id ??
  aggregateData[1]?.average_account_id ??
  aggregateData[0]?.average_account_id ??
  null;

const dailyLimit = toNumber(
  aggregateData[0]?.daily_limit ??
  aggregateData[1]?.daily_limit
);

const remainingAudience = toNumber(aggregateData[0]?.sum_remaining_audience);

const sentToday = toNumber(
  aggregateData[0]?.sent_today ??
  aggregateData[1]?.sent_today
);

return {
  json: {
    account_id: accountId,

    schedule_today: Math.min(
      dailyLimit,
      remainingAudience + sentToday
    ),

    schedule_tomorrow: Math.min(
      dailyLimit,
      Math.max(remainingAudience - dailyLimit, 0)
    ),

    schedule_day_after_tomorrow: Math.min(
      dailyLimit,
      Math.max(remainingAudience - dailyLimit * 2, 0)
    ),
  }
};
